00052     public function reload($id = null, $type = null) {
00053         global $bearsamppRoot, $bearsamppConfig, $bearsamppLang;
00054         Log::reloadClass($this);
00055 
00056         $this->name = $bearsamppLang->getValue(Lang::MEMCACHED);
00057         $this->version = $bearsamppConfig->getRaw(self::ROOT_CFG_VERSION);
00058         parent::reload($id, $type);
00059 
00060         $this->enable = $this->enable && $bearsamppConfig->getRaw(self::ROOT_CFG_ENABLE);
00061         $this->service = new Win32Service(self::SERVICE_NAME);
00062         $this->log = Path::getLogsPath() . '/memcached.log';
00063 
00064         if ($this->bearsamppConfRaw !== false) {
00065             $this->exe = $this->symlinkPath . '/' . $this->bearsamppConfRaw[self::LOCAL_CFG_EXE];
00066             $this->memory = intval($this->bearsamppConfRaw[self::LOCAL_CFG_MEMORY]);
00067             $this->port = intval($this->bearsamppConfRaw[self::LOCAL_CFG_PORT]);
00068         }
00069 
00070         if (!$this->enable) {
00071             Log::info($this->name . ' is not enabled!');
00072             return;
00073         }
00074         if (!is_dir($this->currentPath)) {
00075             Log::error(sprintf($bearsamppLang->getValue(Lang::ERROR_FILE_NOT_FOUND), $this->name . ' ' . $this->version, $this->currentPath));
00076             return;
00077         }
00078         if (!is_dir($this->symlinkPath)) {
00079             Log::error(sprintf($bearsamppLang->getValue(Lang::ERROR_FILE_NOT_FOUND), $this->name . ' ' . $this->version, $this->symlinkPath));
00080             return;
00081         }
00082         if (!is_file($this->bearsamppConf)) {
00083             Log::error(sprintf($bearsamppLang->getValue(Lang::ERROR_CONF_NOT_FOUND), $this->name . ' ' . $this->version, $this->bearsamppConf));
00084             return;
00085         }
00086         if (!is_file($this->exe)) {
00087             Log::error(sprintf($bearsamppLang->getValue(Lang::ERROR_EXE_NOT_FOUND), $this->name . ' ' . $this->version, $this->exe));
00088             return;
00089         }
00090         if (empty($this->memory)) {
00091             Log::error(sprintf($bearsamppLang->getValue(Lang::ERROR_INVALID_PARAMETER), self::LOCAL_CFG_MEMORY, $this->memory));
00092             return;
00093         }
00094         if (empty($this->port)) {
00095             Log::error(sprintf($bearsamppLang->getValue(Lang::ERROR_INVALID_PARAMETER), self::LOCAL_CFG_PORT, $this->port));
00096             return;
00097         }
00098 
00099         $nssm = new Nssm(self::SERVICE_NAME);
00100         $nssm->setDisplayName(APP_TITLE . ' ' . $this->getName());
00101         $nssm->setBinPath($this->exe);
00102         $nssm->setParams(sprintf(self::SERVICE_PARAMS, $this->memory, $this->port));
00103         $nssm->setStart(Nssm::SERVICE_DEMAND_START);
00104         $nssm->setStdout(Path::getLogsPath() . '/memcached.out.log');
00105         $nssm->setStderr(Path::getLogsPath() . '/memcached.err.log');
00106 
00107         $this->service->setNssm($nssm);
00108     }
