00115     protected function replaceAll($params) {
00116         $content = file_get_contents($this->bearsamppConf);
00117 
00118         foreach ($params as $key => $value) {
00119             $content = preg_replace('|' . $key . ' = .*|', $key . ' = ' . '"' . $value.'"', $content);
00120             $this->bearsamppConfRaw[$key] = $value;
00121             switch ($key) {
00122                 case self::LOCAL_CFG_MEMORY:
00123                     $this->memory = intval($value);
00124                     break;
00125                 case self::LOCAL_CFG_PORT:
00126                     $this->port = intval($value);
00127                     break;
00128             }
00129         }
00130 
00131         file_put_contents($this->bearsamppConf, $content);
00132     }
