00167     public function changePort($port, $checkUsed = false, $wbProgressBar = null) {
00168         global $bearsamppWinbinder;
00169 
00170         if (!Util::isValidPort($port)) {
00171             Log::error($this->getName() . ' port not valid: ' . $port);
00172             return false;
00173         }
00174 
00175         $port = intval($port);
00176         $bearsamppWinbinder->incrProgressBar($wbProgressBar);
00177 
00178         $isPortInUse = Util::isPortInUse($port);
00179         if (!$checkUsed || $isPortInUse === false) {
00180             // bearsampp.conf
00181             $this->setPort($port);
00182             $bearsamppWinbinder->incrProgressBar($wbProgressBar);
00183 
00184             // conf
00185             $this->update();
00186             $bearsamppWinbinder->incrProgressBar($wbProgressBar);
00187 
00188             return true;
00189         }
00190 
00191         Log::debug($this->getName() . ' port in used: ' . $port . ' - ' . $isPortInUse);
00192         return $isPortInUse;
00193     }
