00202     public function checkPort($port, $showWindow = false) {
00203         global $bearsamppLang, $bearsamppWinbinder;
00204         $boxTitle = sprintf($bearsamppLang->getValue(Lang::CHECK_PORT_TITLE), $this->getName(), $port);
00205 
00206         if (!Util::isValidPort($port)) {
00207             Log::error($this->getName() . ' port not valid: ' . $port);
00208             return false;
00209         }
00210 
00211         // Use fsockopen instead of memcache_connect to avoid file descriptor leaks in PHP 8.4+
00212         $fp = @fsockopen('127.0.0.1', $port, $errno, $errstr, 1);
00213         if ($fp) {
00214             // Port is open, verify it's memcached by sending a simple command
00215             @stream_set_timeout($fp, 1);
00216             @fwrite($fp, "version\r\n");
00217             $response = @fgets($fp, 128);
00218             @fclose($fp);
00219 
00220             if ($response && strpos($response, 'VERSION') === 0) {
00221                 // Extract version from response (format: "VERSION x.x.x")
00222                 $version = trim(substr($response, 8));
00223                 Log::debug($this->getName() . ' port ' . $port . ' is used by: ' . $this->getName() . ' ' . $version);
00224                 if ($showWindow) {
00225                     $bearsamppWinbinder->messageBoxInfo(
00226                         sprintf($bearsamppLang->getValue(Lang::PORT_USED_BY), $port, $this->getName() . ' ' . $version),
00227                         $boxTitle
00228                     );
00229                 }
00230                 return true;
00231             } else {
00232                 // Port is open but not responding as memcached
00233                 Log::debug($this->getName() . ' port ' . $port . ' is open but not responding as memcached');
00234                 if ($showWindow) {
00235                     $bearsamppWinbinder->messageBoxWarning(
00236                         sprintf($bearsamppLang->getValue(Lang::PORT_NOT_USED_BY), $port),
00237                         $boxTitle
00238                     );
00239                 }
00240                 return false;
00241             }
00242         } else {
00243             // Port is not open
00244             Log::debug($this->getName() . ' port ' . $port . ' is not open');
00245             if ($showWindow) {
00246                 $bearsamppWinbinder->messageBoxError(
00247                     sprintf($bearsamppLang->getValue(Lang::PORT_NOT_USED), $port),
00248                     $boxTitle
00249                 );
00250             }
00251             return false;
00252         }
00253     }
