00275     protected function updateConfig($version = null, $sub = 0, $showWindow = false) {
00276         global $bearsamppLang, $bearsamppApps, $bearsamppWinbinder;
00277 
00278         if (!$this->enable) {
00279             return true;
00280         }
00281 
00282         $version = $version == null ? $this->version : $version;
00283         Log::debug(($sub > 0 ? str_repeat(' ', 2 * $sub) : '') . 'Update ' . $this->name . ' ' . $version . ' config');
00284 
00285         $boxTitle = sprintf($bearsamppLang->getValue(Lang::SWITCH_VERSION_TITLE), $this->getName(), $version);
00286 
00287         $bearsamppConf = str_replace('memcached' . $this->getVersion(), 'memcached' . $version, $this->bearsamppConf);
00288         if (!file_exists($bearsamppConf)) {
00289             Log::error('bearsampp config files not found for ' . $this->getName() . ' ' . $version);
00290             if ($showWindow) {
00291                 $bearsamppWinbinder->messageBoxError(
00292                     sprintf($bearsamppLang->getValue(Lang::BEARSAMPP_CONF_NOT_FOUND_ERROR), $this->getName() . ' ' . $version),
00293                     $boxTitle
00294                 );
00295             }
00296             return false;
00297         }
00298 
00299         $bearsamppConfRaw = parse_ini_file($bearsamppConf);
00300         if ($bearsamppConfRaw === false || !isset($bearsamppConfRaw[self::ROOT_CFG_VERSION]) || $bearsamppConfRaw[self::ROOT_CFG_VERSION] != $version) {
00301             Log::error('bearsampp config file malformed for ' . $this->getName() . ' ' . $version);
00302             if ($showWindow) {
00303                 $bearsamppWinbinder->messageBoxError(
00304                     sprintf($bearsamppLang->getValue(Lang::BEARSAMPP_CONF_MALFORMED_ERROR), $this->getName() . ' ' . $version),
00305                     $boxTitle
00306                 );
00307             }
00308             return false;
00309         }
00310 
00311         // bearsampp.conf
00312         $this->setVersion($version);
00313 
00314         return true;
00315     }
