00344     public function setEnable($enabled, $showWindow = false) {
00345         global $bearsamppConfig, $bearsamppLang, $bearsamppWinbinder;
00346 
00347         if ($enabled == Config::ENABLED && !is_dir($this->currentPath)) {
00348             Log::debug($this->getName() . ' cannot be enabled because bundle ' . $this->getVersion() . ' does not exist in ' . $this->currentPath);
00349             if ($showWindow) {
00350                 $bearsamppWinbinder->messageBoxError(
00351                     sprintf($bearsamppLang->getValue(Lang::ENABLE_BUNDLE_NOT_EXIST), $this->getName(), $this->getVersion(), $this->currentPath),
00352                     sprintf($bearsamppLang->getValue(Lang::ENABLE_TITLE), $this->getName())
00353                 );
00354             }
00355             $enabled = Config::DISABLED;
00356         }
00357 
00358         Log::info($this->getName() . ' switched to ' . ($enabled == Config::ENABLED ? 'enabled' : 'disabled'));
00359         $this->enable = $enabled == Config::ENABLED;
00360         $bearsamppConfig->replace(self::ROOT_CFG_ENABLE, $enabled);
00361 
00362         $this->reload();
00363         if ($this->enable) {
00364             Util::installService($this, $this->port, null, $showWindow);
00365         } else {
00366             Util::removeService($this->service, $this->name);
00367         }
00368     }
